create or replace function public.spend_inventory_budget( p_bucket text, p_rows integer, p_max integer, p_window_seconds integer ) returns integer language plpgsql security definer set search_path = public as $$ declare v_now timestamptz := timezone('utc', now()); v_cost integer := greatest(0, coalesce(p_rows, 0)); v_count integer; v_expires timestamptz; begin insert into public.rate_limits (bucket, count, expires_at) values (p_bucket, v_cost, v_now + make_interval(secs => p_window_seconds)) on conflict (bucket) do update set count = case when public.rate_limits.expires_at <= v_now then v_cost else public.rate_limits.count + v_cost end, expires_at = case when public.rate_limits.expires_at <= v_now then v_now + make_interval(secs => p_window_seconds) else public.rate_limits.expires_at end returning count, expires_at into v_count, v_expires; if v_count > p_max then return greatest(1, ceil(extract(epoch from (v_expires - v_now)))::integer); end if; return 0; end; $$;
comment on function public.spend_inventory_budget(text, integer, integer, integer) is 'Spend a number of inventory rows against an account''s hourly budget. Returns 0 when the read may proceed, or the seconds until the window resets. Shares the rate_limits table with consume_rate_limit; the unit is rows rather than attempts.';
revoke all on function public.spend_inventory_budget(text, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.spend_inventory_budget(text, integer, integer, integer) to service_role;
